const body = $input.first().json.body ?? $input.first().json;
const { scheduled_post_id, platform_post_id, social_account_id, platform_name, campaign_id, published_at, artist_id } = body;

console.log('[DATIAM:notify] content.published — post:', scheduled_post_id, 'platform:', platform_name);

// ─────────────────────────────────────────────────────────────────────────
// TODO: Connect to email or Slack HTTP Request nodes to alert the artist:
//
// Email (SendGrid HTTP Request):
//   POST https://api.sendgrid.com/v3/mail/send
//   Subject: Your post is live on {{platform_name}}!
//
// Slack:
//   POST {{SLACK_WEBHOOK_URL}}
//   text: ':tada: Post published on *{{platform_name}}*\n{{scheduled_post_id}}'
// ─────────────────────────────────────────────────────────────────────────

return [{
  json: {
    handled: true,
    event: 'content.published',
    scheduled_post_id,
    platform_post_id,
    platform_name,
    campaign_id,
    artist_id,
    published_at,
    processed_at: new Date().toISOString()
  }
}];

