const body = $input.first().json.body ?? $input.first().json;
const { trend_id, title, category, trend_score, platform_slug, regions, hashtags, artist_id } = body;

console.log('[DATIAM:notify] trend.detected —', title, '(score:', trend_score, ')');

// ─────────────────────────────────────────────────────────────────────────
