const body = $input.first().json.body ?? $input.first().json;
console.log('[DATIAM:notify] Unknown event — ignoring:', JSON.stringify(body));
return [{ json: { handled: false } }];

const input = $input.first().json;
console.log('[DATIAM:notify] Done:', JSON.stringify(input));
return [{ json: input }];
